func TestIsMxOrNewer(t *testing.T) {
	cases := []struct {
		name    string
		chip    string
		chipErr error
		min     int
		want    bool
	}{
		{"m3 satisfies min=3", "Apple M3 Pro", nil, 3, true},
		{"m3 satisfies min=1", "Apple M3 Pro", nil, 1, true},
